 public static class VoyageSave {
  const string Key="archive.voyage.v6";
  static uint Hash(string s){uint h=2166136261;foreach(char c in s){h^=c;h*=16777619;}return h;}
  public static string Encode(VoyageState s){string body=JsonUtility.ToJson(s);return JsonUtility.ToJson(new SaveEnvelope{body=body,checksum=Hash(body)});}
  public static VoyageState Decode(VoyageConfig cfg,string data){try{var e=JsonUtility.FromJson<SaveEnvelope>(data);if(e==null||string.IsNullOrEmpty(e.body)||e.checksum!=Hash(e.body))return null;var s=JsonUtility.FromJson<VoyageState>(e.body);return VoyageModel.Validate(cfg,s,out _)?s:null;}catch{return null;}}
  public static VoyageState Load(VoyageConfig cfg,out string status){status="";string raw=PlayerPrefs.GetString(Key,"");var s=Decode(cfg,raw);if(s!=null)return s;s=Decode(cfg,PlayerPrefs.GetString(Key+".backup",""));if(s!=null){status="前回の保存を復元しました";return s;}if(raw.Length>0)status="保存を読み込めませんでした。新しい航海を始められます。";return null;}
  public static bool Write(VoyageConfig cfg,VoyageState s){if(!VoyageModel.Validate(cfg,s,out var why)){Debug.LogError("Save rejected: "+why);return false;}try{string previous=PlayerPrefs.GetString(Key,"");if(Decode(cfg,previous)!=null)PlayerPrefs.SetString(Key+".backup",previous);PlayerPrefs.SetString(Key,Encode(s));PlayerPrefs.Save();return true;}catch(Exception e){Debug.LogWarning(e.Message);return false;}}
 }
