  void Awake(){Application.runInBackground=false;AudioListener.pause=false;Application.targetFrameRate=60;if(Application.platform!=RuntimePlatform.WebGLPlayer)Screen.orientation=ScreenOrientation.LandscapeLeft;cfg=JsonUtility.FromJson<VoyageConfig>(Resources.Load<TextAsset>("Voyage/config").text);stories=JsonUtility.FromJson<StoryBook>(Resources.Load<TextAsset>("Voyage/story").text);frames=JsonUtility.FromJson<FrameBook>(Resources.Load<TextAsset>("Voyage/frames").text);var saved=VoyageSave.Load(cfg,out saveStatus);hasSave=saved!=null;model=new VoyageModel(cfg,saved);cast=Resources.Load<Texture2D>("Art/cast-v3");atlases=new[]{Resources.Load<Texture2D>("Voyage/walk-a"),Resources.Load<Texture2D>("Voyage/walk-b"),Resources.Load<Texture2D>("Voyage/walk-c")};font=Resources.Load<Font>("Fonts/NotoSansJP");sound=gameObject.AddComponent<ArkSound>();sound.Theme(0);InitV5();reduceMotion=PlayerPrefs.GetInt("voyage.reduceMotion",0)==1;debug=Application.absoluteURL.Contains("dev=1");disc=new Texture2D(64,64,TextureFormat.RGBA32,false);for(int y=0;y<64;y++)for(int x=0;x<64;x++){float d=Vector2.Distance(new Vector2(x,y),new Vector2(31.5f,31.5f))/32;disc.SetPixel(x,y,new Color(1,1,1,Mathf.Clamp01((1-d)*6)));}disc.Apply();var sceneCamera=new GameObject("SceneCamera").AddComponent<Camera>();sceneCamera.clearFlags=CameraClearFlags.SolidColor;sceneCamera.backgroundColor=paper;sceneCamera.orthographic=true;}
