  public void Visibility(string value){if(exiting)return;bool hidden=value=="hidden";if(hidden==background)return;AudioListener.pause=hidden;if(sound){sound.Background=hidden;sound.Suspended=hidden;}if(hidden){wasPaused=paused;Save();if(screen=="play"&&!paused&&S.mode==0)model.BeginBackground(DateTimeOffset.UtcNow.ToUnixTimeSeconds());background=true;worldHeld=false;praying=false;}else{background=false;model.ApplyAway(DateTimeOffset.UtcNow.ToUnixTimeSeconds());paused=wasPaused;Save();}}
