  public void PrepareExit(){if(exiting)return;exiting=true;Save();background=true;worldHeld=praying=false;StopAllCoroutines();CancelInvoke();AudioListener.pause=true;if(sound){sound.Background=sound.Suspended=true;sound.StopAllCoroutines();sound.CancelInvoke();foreach(var source in sound.GetComponents<AudioSource>())source.Stop();sound.enabled=false;}}
