  void Update(){if(exiting||background)return;UpdateV8();UpdateV7();if(!Input.GetMouseButton(0))worldHeld=false;float dt=Mathf.Min(Time.unscaledDeltaTime,2f);captionTime=Mathf.Max(0,captionTime-dt);fpsTime+=Time.unscaledDeltaTime;fpsFrames++;if(fpsTime>=2){fps=fpsFrames/fpsTime;fpsTime=0;fpsFrames=0;}UpdatePopulationBudget(dt);transition=Mathf.Max(0,transition-dt*1.7f);toastTime-=dt;popAlpha=Mathf.Max(0,popAlpha-dt*.45f);voiceClock+=dt;if(story>=0&&voiceClock<1.5f&&Mathf.FloorToInt(voiceClock*9)!=Mathf.FloorToInt((voiceClock-dt)*9)&&Mathf.FloorToInt(voiceClock*9)%3!=1)sound.Play(stories.pages[story].lines[line].speaker=="ナギ"?5:7);
   if(screen=="play"&&!background&&!paused&&story<0&&panel!="settings"&&Screen.width>=Screen.height){if(worldHeld&&(panel==""||panel=="growth"))model.CommandWorker(selectedWorker,heldAt.x,heldAt.y);else worldHeld=false;model.AdvanceFrame(dt);light=Mathf.MoveTowards(light,model.CrisisActive||model.DemonActive?1:S.demon==1?.65f:model.StormWarning?.28f:S.waveTime>0?.65f:0,dt*.18f);sound.Activity(S.active.Count,model.CrisisActive);ProcessEvents();saveClock+=dt;if(saveClock>5){saveClock=0;Save();}if(S.mode==3){screen="ending";Save();}}
   sound.Background=background;sound.Suspended=background||paused||screen!="play"||story>=0||panel=="settings";publishClock+=dt;if(publishClock>.5f){publishClock=0;Publish();}
