  void ProcessEvents(){foreach(var a in model.arrivals){RecordArrival(a.value);paths.Remove(a.id);popValue+=a.value;popCount++;if(a.first){Tell("新しい仲間  ·  "+cfg.animals[a.species].species);sound.Play(3);if(cfg.animals[a.species].rarity==2&&(S.readEvents&2)==0){S.readEvents|=2;caption="フクロウ博士が、自分の招待状をくわえてきた。";}}}model.arrivals.Clear();popClock+=Time.unscaledDeltaTime;if(popCount>0&&popClock>.65f){popClock=0;popAlpha=1;displayPop=popValue;popValue=0;popCount=0;sound.Play(1);}
   foreach(string e in model.events){EventV8(e);EventV5(e);if(e=="invitation")Tell("空からも、仲間がやって来た。");if(e=="phase:2"){S.readEvents|=4;Tell("仲間と手分けして、群れを迎えよう。");caption="仲間が協力して、動物を迎えています。";}if(e=="lantern"){S.readEvents|=16;Tell("防護完成 · 新しい動物が現れます");caption="遭難信号ではなかった。向こう岸からの、出迎えの灯りだ。";captionTime=30;SetTheme();}if(e=="phase:5"){S.readEvents|=32;Tell("出航の準備が整いました。好きなタイミングで出発できます。");}if(e=="draining"){Tell("最後の動物を誘導中。まもなく出航します。");panel="";}if(e=="sailing"){caption=S.boarded.ToString("N0")+"匹と、新しい岸へ。";sound.Theme(4);sound.Play(4);}}

   model.events.Clear();
  }
