  void Ending(){inputBlocked=restart;Fill(new Rect(0,0,W,H),new Color(.08f,.19f,.23f,.36f));Round(new Rect(W*.15f,85,W*.70f,H-160),paper,14);Text(new Rect(W*.2f,104,W*.6f,48),"航海記  /  明日を乗せる舟",22,teal,TextAnchor.MiddleCenter);Text(new Rect(W*.2f,159,W*.6f,75),"動物たちと、新しい岸へ。",36,ink,TextAnchor.MiddleCenter,true);Text(new Rect(W*.23f,242,W*.54f,81),"海の向こうで、返事の灯りがともる。\n集めたのは、数ではなく。一緒に迎える朝だった。",25,ink,TextAnchor.MiddleCenter);string[] values={S.endBoarded.ToString("N0")+" 匹",S.endTotal.ToString("N0")+" pt",S.endDiscovered+" / 12"};string[] labels={"乗船した動物","累計の貢献","出会った種類"};for(int i=0;i<3;i++){float x=W*.21f+i*W*.195f;Text(new Rect(x,344,W*.19f,30),labels[i],20,muted,TextAnchor.MiddleCenter);Text(new Rect(x,380,W*.19f,57),values[i],34,teal,TextAnchor.MiddleCenter,true);}Text(new Rect(W*.2f,452,W*.6f,43),"航海時間  "+TimeText(S.endTime)+"   ·   成果は保存されています",22,muted,TextAnchor.MiddleCenter);if(Button(new Rect(W*.24f,514,W*.25f,74),"経営を続ける",true,true,24)){model.Continue();screen="play";panel="";SetTheme();Save();}if(Button(new Rect(W*.51f,514,W*.25f,74),"タイトルへ",true,false,24)){Save();screen="title";panel="";paused=false;sound.Theme(0);}}
  static string TimeText(float t)=>((int)t/60)+"分 "+((int)t%60)+"秒";
  void RestartDialog(){Fill(new Rect(0,0,W,H),new Color(ink.r,ink.g,ink.b,.7f));Round(new Rect(W/2-310,205,620,305),paper,12);Text(new Rect(W/2-265,229,530,115),"今の航海を最初からやり直しますか？\nポイント・図鑑・成長がリセットされます。",26,ink,TextAnchor.MiddleCenter);if(Button(new Rect(W/2-266,393,254,76),"今の航海を残す",true,true,22))restart=false;if(Button(new Rect(W/2+12,393,254,76),"最初から始める",true,false,22)){restart=false;model=new VoyageModel(cfg);paths.Clear();hasSave=false;panel="";story=-1;selected=-1;paused=false;caption="";light=0;ResetV7();ResetV8();Begin();}}
  public void DevCommand(string command){if(!debug)return;if(command=="pause"){paused=!paused;return;}if(command=="save"){Save();return;}if(command=="reset"){restart=true;return;}if(command=="early"||command=="middle"||command=="late"||command=="crisis"||command=="boss"){model=new VoyageModel(cfg);float target=command=="early"?45:command=="middle"?550:command=="crisis"?1000:1100;while(S.elapsed<target){model.Tick(.2f);if(model.GuideUnlocked&&S.guideUses==0)model.CallGuide();if(model.GuideAutoReady)model.BuyGuideAuto();if(command=="crisis"&&model.CrisisActive||command=="boss"&&model.DemonActive)break;if(model.AutoUnlocked)model.SetAuto(true,4);if(model.TwilightReady&&S.available>=cfg.lanternCost)model.LightLantern();for(int i=0;i<4;i++)if(model.Buy(i))break;if(model.CanHire)model.Hire();if(model.CanExpand)model.Expand();model.events.Clear();model.arrivals.Clear();}screen="play";paused=false;story=-1;panel="";light=model.CrisisActive?1:0;SetTheme();Tell("開発用の時間短縮プレビューです");}Publish();}
 }
